  45: 0.45,
  50: 0.5,
  55: 0.55,
  60: 0.6,
  70: 0.7,
  90: 0.9,
} as const;

/** Black overlay colours keyed by alpha percent. */
export const scrim = {
  12: "rgba(0,0,0,0.12)",
  18: "rgba(0,0,0,0.18)",
  25: "rgba(0,0,0,0.25)",
  50: "rgba(0,0,0,0.5)",
